 SET @IdProformaProveedorDetalle=CONVERT(int,SCOPE_IDENTITY());
 INSERT dbo.CambiosCotizacion(IdProformaProveedor,IdProformaProveedorDetalle,Origen,CambiosJson,Motivo)
